// Distance from the center (Y axis) for the rings
float dist = pModel.y;

// 'fract' creates crisp stripes (rings); -u_time expands them outward
float anelli = fract(dist * 10.0 - ubuf.u_time * 2.0);

// Slightly softened edges
anelli = smoothstep(0.0, 0.2, anelli) * smoothstep(1.0, 0.8, anelli);

// Background = u_col2, rings = u_col1 (dock colors)
textureCol = mix(ubuf.u_col2, ubuf.u_col1, anelli);
